package com.shahboun.aqim;

import android.app.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class StandbyActivity extends Activity{
 final int G=Color.rgb(8,45,36),GD=Color.rgb(215,180,106),IV=Color.rgb(248,244,235);TextView clock,date,prayer,count,iqama;Handler h=new Handler(Looper.getMainLooper());android.graphics.Typeface cairo;final Runnable tick=new Runnable(){public void run(){refresh();h.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(G);getWindow().setNavigationBarColor(G);try{if(Build.VERSION.SDK_INT>=26)cairo=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception ignored){}LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setPadding(dp(20),dp(18),dp(20),dp(28));r.setBackgroundColor(G);r.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);clock=t("--:--",54,Color.WHITE,true);date=t("",16,IV,false);prayer=t("",24,GD,true);count=t("",19,Color.WHITE,true);iqama=t("",14,IV,false);r.addView(clock,new LinearLayout.LayoutParams(-1,-2));r.addView(date,new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(-1,-2);gp.setMargins(0,dp(20),0,dp(4));r.addView(prayer,gp);r.addView(count,new LinearLayout.LayoutParams(-1,-2));r.addView(iqama,new LinearLayout.LayoutParams(-1,-2));TextView hint=t("لمسة واحدة للخروج",12,IV,false);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.setMargins(0,dp(26),0,0);r.addView(hint,hp);r.setOnClickListener(v->finish());applyInsets(r);setContentView(r);h.post(tick);}
 void refresh(){TimeZone z=TimeZone.getTimeZone(getSharedPreferences("aqim",MODE_PRIVATE).getString("tzId",TimeZone.getDefault().getID()));Date now=new Date();SimpleDateFormat tf=new SimpleDateFormat(getSharedPreferences("aqim",MODE_PRIVATE).getBoolean("time24",true)?"HH:mm:ss":"hh:mm:ss a",Locale.US);tf.setTimeZone(z);SimpleDateFormat df=new SimpleDateFormat("EEEE، d MMMM yyyy",new Locale("ar"));df.setTimeZone(z);clock.setText(tf.format(now));date.setText(df.format(now));try{String[] n=MainActivity.nextPrayerInfo(this);prayer.setText("الصلاة القادمة: "+n[0]+" • "+n[1]);count.setText("باقي "+n[2]);iqama.setText(n.length>4?n[4]:"");}catch(Exception e){prayer.setText("أَقِمْ | رفيق المسلم");count.setText("");iqama.setText("");}}
 TextView t(String s,int z,int c,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(c);x.setGravity(Gravity.CENTER);x.setPadding(dp(6),dp(6),dp(6),dp(6));if(cairo!=null)x.setTypeface(cairo,b?1:0);return x;}int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}void applyInsets(View v){if(Build.VERSION.SDK_INT>=21)v.setOnApplyWindowInsetsListener((x,i)->{int top,bottom,left,right;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets z=i.getInsets(WindowInsets.Type.systemBars());top=z.top;bottom=z.bottom;left=z.left;right=z.right;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();left=i.getSystemWindowInsetLeft();right=i.getSystemWindowInsetRight();}x.setPadding(dp(20)+left,dp(18)+top,dp(20)+right,dp(28)+bottom);return i;});}@Override protected void onDestroy(){h.removeCallbacks(tick);super.onDestroy();}
}